// Builds src/docs.generated.ts from docs/*.md + operator.json: front matter, operator details filled in,
// HTML rendered at build time (no Markdown library in the app), sha256 of the final text.
// Run: pnpm --filter @hub/legal build (also runs before dev/build). The generated file is committed.
import { createHash } from 'node:crypto';
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { marked } from 'marked';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const operator = JSON.parse(readFileSync(path.join(root, 'operator.json'), 'utf8')) as Record<string, string>;
const fields = Object.keys(operator).filter((k) => !k.startsWith('_'));
const missing = fields.filter((k) => !String(operator[k] ?? '').trim());

function fill(md: string) {
  return md.replace(/\{\{(\w+)\}\}/g, (_, k: string) => {
    const v = String(operator[k] ?? '').trim();
    return v || `[${k.replace(/_/g, ' ')} to be confirmed]`;
  });
}

const docs = readdirSync(path.join(root, 'docs'))
  .filter((f) => f.endsWith('.md'))
  .sort()
  .map((file) => {
    const raw = readFileSync(path.join(root, 'docs', file), 'utf8').replace(/\r\n/g, '\n');
    const m = /^---\n([\s\S]*?)\n---\n([\s\S]*)$/.exec(raw);
    if (!m) throw new Error(`${file}: missing front matter`);
    const meta = Object.fromEntries(
      m[1]!.split('\n').map((line) => {
        const i = line.indexOf(':');
        return [line.slice(0, i).trim(), line.slice(i + 1).trim()];
      }),
    ) as Record<string, string>;
    const usedTokens = [...m[2]!.matchAll(/\{\{(\w+)\}\}/g)].map((t) => t[1]!);
    const unknown = usedTokens.filter((t) => !fields.includes(t));
    if (unknown.length) throw new Error(`${file}: unknown placeholders ${unknown.join(', ')}`);
    const bodyMd = fill(m[2]!.trim()) + '\n';
    return {
      kind: meta.kind!,
      locale: meta.locale!,
      version: meta.version!,
      title: meta.title!,
      requiresAcceptance: meta.requires_acceptance === 'true',
      summary: meta.summary ?? '',
      bodyMd,
      html: marked.parse(bodyMd, { async: false, gfm: true }) as string,
      sha256: createHash('sha256').update(bodyMd).digest('hex'),
      missingOperatorFields: [...new Set(usedTokens.filter((t) => missing.includes(t)))],
    };
  });

const out = `// GENERATED by packages/legal/scripts/build.ts from docs/*.md and operator.json. Do not edit by hand.
export const LEGAL_DOCS = ${JSON.stringify(docs, null, 2)} as const;
export const OPERATOR_MISSING: readonly string[] = ${JSON.stringify(missing)};
`;
writeFileSync(path.join(root, 'src', 'docs.generated.ts'), out);
console.log(`legal: ${docs.length} documents built${missing.length ? `; operator details missing: ${missing.join(', ')}` : ''}`);
